function installStageADetectorSumPatchRobust()
%INSTALLSTAGEADETECTORSUMPATCHROBUST Patch Stage A to detector-summed ISM.
%
%   Run once in MATLAB from the Aberration_estimation path:
%
%       installStageADetectorSumPatchRobust
%
%   It modifies calibrateISMFromConfocalSum.m in-place and creates a
%   timestamped backup.  The patched Stage-A model becomes:
%
%       vol(y,x,z) = sum_k normalizedStackAirInterfaceZPlanes(...)(y,x,k,z)
%
%   instead of the previous excitation-only/open-pinhole widefield
%   approximation.  This makes effective-NA and aberration fitting act on the
%   measured detector-summed ISM observable.

    target = fullfile(fileparts(mfilename('fullpath')), ...
        'calibrateISMFromConfocalSum.m');
    if exist(target, 'file') ~= 2
        error('installStageADetectorSumPatchRobust:MissingFile', ...
            'Could not find %s', target);
    end

    txt = fileread(target);
    stamp = datestr(now, 'yyyymmdd_HHMMSS');
    backup = [target '.bak_stageA_detector_sum_' stamp];
    fid = fopen(backup, 'w');
    if fid < 0
        error('installStageADetectorSumPatchRobust:BackupFailed', ...
            'Could not create backup %s', backup);
    end
    fwrite(fid, txt);
    fclose(fid);

    txt = replaceConfocalVolumeFunction(txt);
    txt = addSafeExportFallback(txt);

    fid = fopen(target, 'w');
    if fid < 0
        error('installStageADetectorSumPatchRobust:WriteFailed', ...
            'Could not write %s', target);
    end
    fwrite(fid, txt);
    fclose(fid);

    fprintf('Patched detector-summed Stage A in:\n  %s\n', target);
    fprintf('Backup saved as:\n  %s\n', backup);
end

function txt = replaceConfocalVolumeFunction(txt)
    startToken = 'function vol = confocalAirInterfaceVolume(sim, coeffs, planeZ, x0, y0)';
    nextToken = 'function p = clampConfocal';
    iStart = strfind(txt, startToken);
    iNext = strfind(txt, nextToken);
    if isempty(iStart) || isempty(iNext)
        error('installStageADetectorSumPatchRobust:AnchorNotFound', ...
            'Could not find expected local-function anchors.');
    end
    iStart = iStart(1);
    iNext = iNext(find(iNext > iStart, 1, 'first'));
    if isempty(iNext)
        error('installStageADetectorSumPatchRobust:BadAnchorOrder', ...
            'Function anchors were found in the wrong order.');
    end

    newBlock = detectorSumFunctionText();
    txt = [txt(1:iStart-1) newBlock txt(iNext:end)];
end

function block = detectorSumFunctionText()
    block = sprintf('%s\n', ...
        'function vol = confocalAirInterfaceVolume(sim, coeffs, planeZ, x0, y0)', ...
        '    % Detector-summed ISM air-interface bead volume. This is the', ...
        '    % measured Stage-A observable: sum of the 23 detector scan images,', ...
        '    % not an ideal excitation-only/open-pinhole widefield approximation.', ...
        '    % The finite detector-array collection weighting is included in the', ...
        '    % effective-NA and aberration fit.', ...
        '    sim = ensureStageADetectorGeometry(sim);', ...
        '    stack = normalizedStackAirInterfaceZPlanes(sim, coeffs, planeZ, x0, y0, 0);', ...
        '    vol = squeeze(sum(stack, 3));       % [y x plane], summed over detectors', ...
        '    if ndims(vol) == 2', ...
        '        vol = reshape(vol, size(stack,1), size(stack,2), 1);', ...
        '    end', ...
        '    total = sum(vol(:));', ...
        '    if total > 0, vol = vol/total; end', ...
        'end', ...
        '', ...
        'function sim = ensureStageADetectorGeometry(sim)', ...
        '    if ~isfield(sim, ''detectorLayout'') || isempty(sim.detectorLayout)', ...
        '        sim.detectorLayout = ''honeycomb23'';', ...
        '    end', ...
        '    if ~isfield(sim, ''detectorPixelShape'') || isempty(sim.detectorPixelShape)', ...
        '        sim.detectorPixelShape = ''hex'';', ...
        '    end', ...
        '    if ~isfield(sim, ''detXY'') || isempty(sim.detXY)', ...
        '        [sim.detXY, sim.detectorIndexGrid, sim.detectorLayoutInfo] = ...', ...
        '            detectorLayout(sim.detectorLayout, sim.detPitch);', ...
        '    end', ...
        '    sim.nDet = size(sim.detXY, 1);', ...
        '    sim.detectorGridSize = size(sim.detectorIndexGrid);', ...
        'end', ...
        '');
end

function txt = addSafeExportFallback(txt)
    txt = strrep(txt, ...
        'exportgraphics(fig, outFile, ''Resolution'', 160); close(fig);', ...
        'safeExportFigure(fig, outFile, 160); close(fig);');

    if contains(txt, 'function safeExportFigure(fig, outFile, resolution)')
        return;
    end

    helper = sprintf('%s\n', ...
        '', ...
        'function safeExportFigure(fig, outFile, resolution)', ...
        '    if nargin < 3 || isempty(resolution)', ...
        '        resolution = 160;', ...
        '    end', ...
        '    drawnow;', ...
        '    try', ...
        '        exportgraphics(fig, outFile, ''Resolution'', resolution);', ...
        '    catch err', ...
        '        warning(''calibrateISMFromConfocalSum:ExportFallback'', ...', ...
        '            ''exportgraphics failed for %s: %s. Falling back to print().'', ...', ...
        '            outFile, err.message);', ...
        '        drawnow;', ...
        '        set(fig, ''PaperPositionMode'', ''auto'');', ...
        '        print(fig, outFile, ''-dpng'', sprintf(''-r%d'', resolution));', ...
        '    end', ...
        'end');

    txt = [txt helper];
end
